duscope top {root} --files --min-size 10M --limit 100 --size apparent --json | python3 -c "
import json,sys,collections
d=json.load(sys.stdin)
print(d.get('warnings'),len(d['entries']))
c=collections.defaultdict(list)
for e in d['entries']:
    c[e['path'].rsplit('/',1)[1]].append((e['path'],e.get('size')))
for k,v in c.items():
    if len(v)>1: print(k,v)
"

